INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES
('faq','FAQ','Frequently asked questions about INFOROVA','<h2>Frequently Asked Questions</h2><h3>Is INFOROVA an official government website?</h3><p>No. INFOROVA is an independent information website. Always verify important information with the official authority.</p><h3>How often is content updated?</h3><p>We update articles when new information is available and review important dates when possible.</p>'),
('editorial-policy','Editorial Policy','How INFOROVA publishes and reviews content','<h2>Editorial Policy</h2><p>We aim to publish clear, useful and responsibly sourced information. Where an article concerns an official process, readers are encouraged to verify the latest notice from the primary authority.</p>'),
('advertise','Advertise','Advertising information for INFOROVA','<h2>Advertising</h2><p>INFOROVA may display advertisements from third-party advertising partners. Ad placements are labeled and are intended to be separate from editorial content.</p>'),
('accessibility','Accessibility','INFOROVA accessibility statement','<h2>Accessibility</h2><p>We aim to keep pages readable on phones and desktops, use semantic headings and provide keyboard-friendly controls where practical.</p>');
INSERT IGNORE INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES
((SELECT id FROM categories WHERE slug='sarkari-job'),'Government Job Application Checklist','government-job-application-checklist','A practical checklist for preparing a government job application.','<p>A government job application looks simple on the surface: fill a form, upload some documents, pay a fee. In practice, most rejections come from small gaps in preparation rather than a lack of eligibility. A clear checklist, followed in order, removes almost all of that risk.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 Start preparing documents the day a notice is published, not the day before it closes</li><li>👉 Photo and signature files usually have strict size and format limits</li><li>👉 A single missing certificate is one of the most common reasons a complete-looking form gets rejected</li><li>👉 Keep both a digital folder and a printed copy of everything you submit</li></ul></div><h2 id="before-you-start-the-form">📌 Before You Start the Form</h2><p>Read the full notice once for a general understanding, then a second time specifically to list every document, deadline and fee it mentions. Many notices also state a category-wise relaxation in age or fee, which is easy to miss on a quick read.</p><h2 id="the-core-documents-to-collect">🎯 The Core Documents to Collect</h2><p>Most government application forms ask for a consistent set of documents, though the exact list always depends on the specific notice.</p><ul><li>✔️ A valid photo ID, matching the name used on the form exactly</li><li>✔️ Educational certificates and mark sheets for every qualification claimed</li><li>✔️ Category or reservation certificate from the correct issuing authority, if applicable</li><li>✔️ A recent passport-size photograph and signature, scanned to the exact size and format requested</li></ul><h2 id="a-simple-final-review">💡 A Simple Final Review</h2><p>Before final submission, compare every field on the form against your certificates, since a small mismatch in a name, date or spelling can cause problems later during document verification. Submitting two or three days before the deadline also avoids last-minute portal slowdowns.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Do I need to upload documents at the time of the online form, or only later?</h3><p>This depends on the recruiting authority. Some forms require uploads immediately, while others only ask for documents at a later verification stage. The notice always states which applies.</p></div><div class="faq-item"><h3>❓ What happens if a document is uploaded in the wrong format?</h3><p>Many portals reject the file automatically at the upload step itself, so it is best to resize and convert files before starting the form rather than during it.</p></div><div class="faq-item"><h3>❓ Should I keep a copy of the submitted form?</h3><p>Yes. Save or print the confirmation page and the final submitted form, since it is often needed for admit card or verification purposes later.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>A government job application rewards preparation more than last-minute effort. Reading the notice carefully, collecting documents early and reviewing the form before submission covers most of what actually determines whether an application is accepted.</p></div>','published',NOW()),
((SELECT id FROM categories WHERE slug='exam-news'),'Exam Date Update: How to Verify Official Notices','exam-date-update-how-to-verify-official-notices','How to confirm exam dates and avoid relying on outdated posts.','<p>Exam dates change more often than most candidates expect, and outdated information continues to circulate on social media long after an official update is issued. Learning to verify a date directly, rather than trusting whichever post appears first, is one of the simplest habits that protects an entire exam plan.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 The issuing authority''s own website is always the final word on a date, not a forwarded message</li><li>👉 A genuine notice carries a notice number, date and official letterhead or seal</li><li>👉 Screenshots without a source link are the easiest kind of misinformation to spread</li><li>👉 Setting an independent reminder avoids relying on someone else noticing a change first</li></ul></div><h2 id="where-a-real-update-comes-from">📌 Where a Real Update Comes From</h2><p>An official exam date, or any change to it, is published on the recruiting or examination authority''s own website, and often through a linked press release or an admit card update. Coaching pages, forums and social media accounts may repost this information, sometimes accurately and sometimes with delay or error.</p><h2 id="recognizing-an-outdated-or-fake-post">🎯 Recognizing an Outdated or Fake Post</h2><p>A few consistent signs separate a reliable update from an outdated or incorrect one.</p><ul><li>✔️ No notice number or reference date included</li><li>✔️ The date does not match what is currently shown on the official website</li><li>✔️ The post is significantly older than its share date suggests</li><li>✔️ It asks you to click an unrelated external link to "confirm" the date</li></ul><h2 id="building-a-quick-verification-habit">💡 Building a Quick Verification Habit</h2><p>Before making any decision based on a date, such as travel or leave planning, open the official website directly rather than relying on a shared screenshot. Bookmarking the exact notice or admit card page in advance makes this a fast, two-minute check rather than a search each time.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Why do exam dates change so often?</h3><p>Postponements can happen for many administrative reasons, including venue availability, legal matters or unforeseen circumstances. The reason is usually explained in the official notice itself.</p></div><div class="faq-item"><h3>❓ Is it safe to trust a well-known coaching page''s update?</h3><p>Many are accurate and quick, but they are still a secondary source. Cross-checking against the official website before acting on the date is still worthwhile.</p></div><div class="faq-item"><h3>❓ What should I do if I cannot find any official update?</h3><p>Continue preparing according to the last confirmed official date rather than an unverified rumor, and check back on the official website periodically.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>A short habit of checking the original source before reacting to any exam date update prevents the wasted stress and misplanning that comes from outdated or unofficial posts.</p></div>','published',NOW()),
((SELECT id FROM categories WHERE slug='exam-prep'),'How to Make Better Revision Notes','how-to-make-better-revision-notes','Simple methods for organizing revision notes without making them unnecessarily long.','<p>Revision notes are meant to save time closer to an exam, but many students end up rewriting entire chapters, which takes almost as long as the original study and adds little value when time is short. A few structural habits make notes genuinely faster to review later.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 Good revision notes are built to be scanned quickly, not read like a textbook</li><li>👉 Headings and short definitions are more useful under time pressure than full paragraphs</li><li>👉 Notes should highlight what you personally find difficult to recall, not everything in a chapter</li><li>👉 A one-page summary per topic is usually more useful than several detailed pages</li></ul></div><h2 id="what-good-revision-notes-actually-look-like">📌 What Good Revision Notes Actually Look Like</h2><p>Effective revision notes are short, structured with clear headings, and written in your own words rather than copied directly from a textbook. The goal is to trigger memory quickly during a fast review, not to explain the topic from scratch each time.</p><h2 id="a-simple-structure-to-follow">🎯 A Simple Structure to Follow</h2><p>A consistent format across every topic makes review faster because you always know where to look for a specific kind of information.</p><ul><li>✔️ A one-line definition or summary at the top</li><li>✔️ Key points as short bullets, not full sentences</li><li>✔️ A separate section only for points you personally keep forgetting</li><li>✔️ Practice questions or common mistakes noted at the bottom</li></ul><h2 id="reviewing-notes-instead-of-just-rewriting-them">💡 Reviewing Notes Instead of Just Rewriting Them</h2><p>Notes only help if they are actually revisited. Scheduling short, repeated review sessions works better than writing detailed notes once and never opening them again before the exam.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Should I rewrite my notes multiple times?</h3><p>Rewriting the same information repeatedly is usually less useful than actively testing yourself on it. Update notes only when you learn something new or correct a mistake.</p></div><div class="faq-item"><h3>❓ Are digital notes better than handwritten ones?</h3><p>Both work well; the more important factor is whether the notes are structured clearly and actually reviewed regularly, not the format they are kept in.</p></div><div class="faq-item"><h3>❓ How long before an exam should revision notes be ready?</h3><p>Ideally notes are built gradually throughout preparation, so that only quick review remains in the final days rather than note-making itself.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>Short, well-structured revision notes that are actually reviewed matter far more than long, detailed ones written once. Focus on scannable structure and personal weak points rather than length.</p></div>','published',NOW()),
((SELECT id FROM categories WHERE slug='results'),'How to Check an Exam Result Safely','how-to-check-an-exam-result-safely','A guide to finding the correct result page and avoiding unofficial links.','<p>Result day often brings a flood of links shared across messaging apps and social media, and not all of them lead to the genuine result page. Knowing exactly where to look, and what to avoid, keeps the process quick and safe.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 The examination authority''s own website is the only fully reliable source for a result</li><li>👉 A genuine result page usually asks only for a roll number or registration ID, not a password</li><li>👉 Unofficial "result checker" sites sometimes ask for unnecessary personal details</li><li>👉 Saving or screenshotting the result once it appears avoids depending on a slow server later</li></ul></div><h2 id="where-to-check-first">📌 Where to Check First</h2><p>The examination authority''s own website, or a link published directly from it, is the correct place to check a result. Bookmarking this page in advance saves time on a day when servers are often slow due to heavy traffic.</p><h2 id="spotting-an-unofficial-result-page">🎯 Spotting an Unofficial Result Page</h2><p>A few warning signs usually indicate a page is not the genuine result source.</p><ul><li>✔️ It asks for a password, bank detail or unrelated personal information</li><li>✔️ The web address does not match the known official domain</li><li>✔️ It displays excessive pop-up ads before showing any result field</li><li>✔️ It was shared only through a forwarded message with no source link</li></ul><h2 id="what-to-do-once-the-result-is-out">💡 What to Do Once the Result Is Out</h2><p>Once the genuine result appears, save a screenshot or download the official scorecard if one is provided, since official servers can become slow or temporarily unavailable again shortly after results are announced.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Is it safe to check a result through a third-party app?</h3><p>Only if the app is well known and clearly pulls data directly from the official source. When in doubt, the authority''s own website remains the safer option.</p></div><div class="faq-item"><h3>❓ What if the official website is too slow to load?</h3><p>This is common right after a result is announced due to heavy traffic. Waiting a short while and trying again is usually more reliable than switching to an unofficial site.</p></div><div class="faq-item"><h3>❓ Should I trust a result shared as a screenshot?</h3><p>Always verify it directly on the official website before treating it as confirmed, since screenshots can be outdated, incomplete or altered.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>Checking a result directly on the official website, and being cautious of pages that ask for unnecessary information, is the simplest way to avoid both misinformation and privacy risks on result day.</p></div>','published',NOW()),
((SELECT id FROM categories WHERE slug='scholarships'),'Scholarship Application Preparation Guide','scholarship-application-preparation-guide','What to prepare before completing a scholarship application.','<p>A strong scholarship application rarely comes together at the last minute. Most of the work is in preparation, gathering the right documents, and understanding eligibility clearly, well before the actual form is filled out.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 Eligibility criteria should be checked line by line before assuming you qualify</li><li>👉 Financial and academic documents often take the longest to arrange, so start early</li><li>👉 A scholarship essay is usually judged on clarity and honesty, not length</li><li>👉 Saving a copy of the completed submission protects you if a technical issue occurs later</li></ul></div><h2 id="checking-eligibility-carefully">📌 Checking Eligibility Carefully</h2><p>Scholarship notices often list several conditions together, such as income limits, academic percentage, category and course requirements. Missing even one specific line can mean an otherwise strong application is not considered, so it is worth reading the eligibility section more than once.</p><h2 id="documents-that-usually-take-the-longest">🎯 Documents That Usually Take the Longest</h2><p>Some documents require time from another office or authority, so requesting them early avoids a last-minute scramble.</p><ul><li>✔️ Income certificate from the relevant local or revenue office</li><li>✔️ Latest academic mark sheets and a bonafide student certificate</li><li>✔️ Bank account details in the applicant''s own name, where required</li><li>✔️ Category certificate, if the scholarship has a reserved category component</li></ul><h2 id="submitting-with-confidence">💡 Submitting With Confidence</h2><p>Before the final submission, recheck that every uploaded document is clear, correctly named if a format is specified, and matches the details entered in the form itself. A short, honest personal statement is usually more effective than an overly long one.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Can I apply for more than one scholarship at the same time?</h3><p>Often yes, unless a specific scholarship''s rules state otherwise, but always confirm this from the individual scheme''s own terms.</p></div><div class="faq-item"><h3>❓ What if I am not fully sure I meet one eligibility condition?</h3><p>Contact the scholarship''s official helpdesk or read the frequently asked questions on its website rather than assuming either way.</p></div><div class="faq-item"><h3>❓ Does a scholarship essay need to be long to be effective?</h3><p>No. A clear, honest and specific essay is generally valued more than one that is simply long.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>Careful eligibility checking, early document collection and a clear, honest application are what most reliably improve a scholarship application, far more than last-minute effort.</p></div>','published',NOW()),
((SELECT id FROM categories WHERE slug='career-guide'),'Building a Simple Career Research Plan','building-a-simple-career-research-plan','A practical framework for comparing study and career options.','<p>Choosing between study and career paths can feel overwhelming when every option seems to need a decision at once. A simple, structured research plan makes the process far more manageable by breaking it into a few clear steps.</p><div class="quick-facts"><h3>✅ Key Takeaways</h3><ul><li>👉 Start with your own interests and strengths before comparing external options</li><li>👉 Compare real education requirements and timelines, not just a course''s reputation</li><li>👉 Talking to someone actually working in a field is more useful than reading about it alone</li><li>👉 A career research plan works best when revisited every few months, not decided once</li></ul></div><h2 id="starting-with-yourself">📌 Starting With Yourself</h2><p>Before comparing external options, it helps to note down what subjects or tasks you naturally enjoy, and what kind of work environment suits you, whether that is structured and stable or flexible and varied. This becomes the filter for judging every option that follows.</p><h2 id="comparing-options-properly">🎯 Comparing Options Properly</h2><p>Once a few directions look interesting, compare them on the same practical points.</p><ul><li>✔️ Exact education or certification requirements, and how long they take</li><li>✔️ Typical day-to-day work involved, not just the job title</li><li>✔️ Entry-level opportunities available in your own region</li><li>✔️ Long-term learning or growth the field usually requires</li></ul><h2 id="talking-to-people-and-trusted-sources">💡 Talking to People and Trusted Sources</h2><p>Speaking with a teacher, mentor or someone already working in a field of interest often reveals practical details that are not obvious from a course brochure alone. Trusted adults and qualified counselors are especially useful for weighing options involving major financial or time commitments.</p><h2 id="frequently-asked-questions">🙋 Frequently Asked Questions</h2><div class="faq-item"><h3>❓ Is it normal to still be unsure after doing this research?</h3><p>Yes, and that is common. The goal of this process is to narrow options with real information, not necessarily to reach full certainty immediately.</p></div><div class="faq-item"><h3>❓ How often should a career plan be reviewed?</h3><p>Revisiting it every few months, or after any major new information, keeps the plan realistic as circumstances and interests change.</p></div><div class="faq-item"><h3>❓ Should career choice be based only on expected salary?</h3><p>Salary is one useful factor, but day-to-day work, growth opportunities and personal fit are equally important for a decision you will live with long-term.</p></div><div class="quick-facts"><h3>💬 In Short</h3><p>A structured comparison built on your own strengths, real requirements and honest conversations leads to a far more confident career decision than comparing options by reputation alone.</p></div>','published',NOW());
